import httpximport asyncioimport jsonimport osimport reimport sysimport randomimport timefrom urllib.parse import urlencode# ══════════════════════════════════════════════════════════════════════════════# Config# ══════════════════════════════════════════════════════════════════════════════POLL_BETKING  = 1.0POLL_SR       = 1.0STAKE_AMOUNT  = 20FIXED_ODD     = 1.20   # placeholder — overwritten by allowOddChanges at placementHANDICAP_TYPE_ID = 10636# Positive line → selection "1" (home losing)# Negative line → selection "2" (away losing)COLLECT_LINES = [5.5, -5.5, 4.5, -4.5, 3.5, -3.5, 2.5, -2.5]# (loser_points, line_home_losing, line_away_losing)SR_TRIGGERS = [    (6, 5.5,  -5.5),    (7, 4.5,  -4.5),    (8, 3.5,  -3.5),    (9, 2.5,  -2.5),]SR_URL = (    "https://lmt.fn.sportradar.com/common/en/Etc:UTC"    "/gismo/match_timelinedelta/{sr_match_id}?T={token}")SR_HEADERS = {    "User-Agent":      "Mozilla/5.0 (X11; Linux x86_64; rv:140.0) Gecko/20100101 Firefox/140.0",    "Accept":          "*/*",    "Accept-Language": "en-US,en;q=0.5",    "Accept-Encoding": "gzip, deflate, br",    "Origin":          "https://m.betking.com",    "Referer":         "https://m.betking.com/",    "Sec-Fetch-Dest":  "empty",    "Sec-Fetch-Mode":  "cors",    "Sec-Fetch-Site":  "cross-site",    "Sec-Gpc":         "1",    "Te":              "trailers",}EVENT_URL = (    "https://m.betking.com/en-ng/sports/live/api/event"    "?areaId=4&fixtureId={fixture_id}"    "&_data=routes%2F%28%24locale%29.sports.live.api.event")PLACEBET_URL = (    "https://m.betking.com/en-ng/sports/action/placebet"    "?_data=routes%2F%28%24locale%29.sports.action.placebet")EVENT_HEADERS = {    "User-Agent":      "Mozilla/5.0 (X11; Linux x86_64; rv:140.0) Gecko/20100101 Firefox/140.0",    "Accept":          "*/*",    "Accept-Language": "en-US,en;q=0.5",    "Dnt":             "1",    "Sec-Gpc":         "1",    "Sec-Fetch-Dest":  "empty",    "Sec-Fetch-Mode":  "cors",    "Sec-Fetch-Site":  "same-origin",    "Priority":        "u=4",    "Te":              "trailers",}PLACEBET_HEADERS = {    "User-Agent":      "Mozilla/5.0 (X11; Linux x86_64; rv:140.0) Gecko/20100101 Firefox/140.0",    "Accept":          "*/*",    "Accept-Language": "en-US,en;q=0.5",    "Referer":         "https://m.betking.com/en-ng",    "Content-Type":    "application/x-www-form-urlencoded;charset=UTF-8",    "Origin":          "https://m.betking.com",    "Dnt":             "1",    "Sec-Gpc":         "1",    "Sec-Fetch-Dest":  "empty",    "Sec-Fetch-Mode":  "cors",    "Sec-Fetch-Site":  "same-origin",    "Priority":        "u=4",    "Te":              "trailers",}# ══════════════════════════════════════════════════════════════════════════════# DB Helpers# ══════════════════════════════════════════════════════════════════════════════def _load_db_config() -> dict:    base   = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))    config = {}    with open(os.path.join(base, "db.txt"), "r") as f:        for line in f:            line = line.strip()            if not line or line.startswith("#"):                continue            if "=" in line:                k, _, v = line.partition("=")                config[k.strip()] = v.strip().strip('"')    return configdef _get_supabase():    from supabase import create_client    config = _load_db_config()    return create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])def _load_cookie() -> str:    try:        sb = _get_supabase()        return sb.table("betking").select("cookie").eq("id", 1).single().execute().data["cookie"]    except Exception as e:        print(f"[analyzer] cookie err        : {e}")        return ""def _load_sr_token() -> str:    """    Read today's Sportradar token directly from sp_tracker.    Uses inline supabase call to avoid import path issues.    Day format matches _day_label() in betlist.py: d/m/YYYY.    """    try:        from datetime import datetime, timezone        sb      = _get_supabase()        now     = datetime.now(timezone.utc)        day_str = f"{now.day}/{now.month}/{now.year}"        row     = sb.table("sp_tracker").select("token").eq("name", "chukwuebuka").eq("day", day_str).execute()        if row.data:            token = row.data[0].get("token") or ""            if token:                return token        print(f"[analyzer] sr token          : not found in sp_tracker for {day_str}")        return ""    except Exception as e:        print(f"[analyzer] sr token err      : {e}")        return ""# ══════════════════════════════════════════════════════════════════════════════# Score Parsing# ══════════════════════════════════════════════════════════════════════════════def _parse_period_scores(period_scores: str) -> list[tuple[int, int]]:    sets = []    for part in period_scores.split(" - "):        part = part.strip()        if not part or ":" not in part:            continue        try:            h, a = part.split(":")            sets.append((int(h), int(a)))        except ValueError:            continue    return setsdef _current_set_index(sets: list[tuple[int, int]]) -> int:    return len(sets)def _last_set_score(sets: list[tuple[int, int]]) -> tuple[int, int]:    return sets[-1] if sets else (0, 0)def _is_between_sets(sets: list[tuple[int, int]]) -> bool:    if not sets:        return False    return sets[-1] == (0, 0)def _set_has_started(sets: list[tuple[int, int]]) -> bool:    if not sets:        return False    h, a = sets[-1]    return (h + a) >= 1# ══════════════════════════════════════════════════════════════════════════════# Sportradar Match ID# ══════════════════════════════════════════════════════════════════════════════def _extract_sr_id(event: dict, markets: list) -> str | None:    for obj in [event] + markets:        source = obj.get("source") or {}        pid    = source.get("providerId", "")        m      = re.search(r"sr:match:(\d+)", pid)        if m:            return m.group(1)    return None# ══════════════════════════════════════════════════════════════════════════════# Sportradar Response Parsing# ══════════════════════════════════════════════════════════════════════════════def _sr_last_period_score(sr_data: dict, period_num: int) -> tuple[int, int] | None:    try:        match = sr_data.get("doc", [{}])[0].get("data", {}).get("match")        if not match:            return None        periods = match.get("periods") or {}        if not periods:            return None        key = f"p{period_num}"        if key not in periods:            return None  # current period not scored yet — between sets        p = periods[key]        return int(p["home"]), int(p["away"])    except Exception:        return Nonedef _sr_current_period(sr_data: dict) -> int | None:    try:        match = sr_data.get("doc", [{}])[0].get("data", {}).get("match")        if not match:            return None        p = int(match.get("p", 0))        if p < 1 or p > 5:            return None  # break period (e.g. 31) or not started        return p    except Exception:        return None# ══════════════════════════════════════════════════════════════════════════════# Payload Builder  (called at collection time, not at trigger time)# ══════════════════════════════════════════════════════════════════════════════def _build_ready_payload(    market: dict,    sel: dict,    line: float,    target_set: int,    event: dict,    period_scores: str,    cookie: str,) -> dict:    """    Builds and encodes the COMPLETE bet body at market collection time.    Generates tx_id now. Stores the pre-encoded body string in the payload.    At trigger time, _place_bet() only needs to send what is already here.    """    specs       = market.get("specifiers", {})    spec_val    = str(specs.get("gamenr") or market.get("specialValue", str(target_set)))    market_name = f"Set {spec_val} - Point Handicap"    sel_name    = f"{sel['name']} ({spec_val})"    odd   = FIXED_ODD    stake = STAKE_AMOUNT    win   = round(stake * odd, 2)    tx_id = str(random.randint(10_000_000_000, 99_999_999_999))    match_id        = event.get("id") or event.get("fixtureId")    match_name      = event.get("name", "?")    category_id     = event.get("categoryId")    category_name   = event.get("categoryName", "")    event_date      = event.get("date", "")    tournament_id   = event.get("tournamentId")    tournament_name = event.get("tournamentName", "?")    grouping = {        "grouping":           1,        "combinations":       1,        "minWin":             win,        "minWinNet":          win,        "netStakeMinWin":     win,        "maxWin":             win,        "maxWinNet":          win,        "netStakeMaxWin":     win,        "minBonus":           0,        "maxBonus":           0,        "minPercentageBonus": 0,        "maxPercentageBonus": 0,        "stake":              stake,        "netStake":           stake,        "selected":           True,    }    coupon = {        "betCoupon": {            "isClientSideCoupon":  True,            "couponTypeId":        1,            "minWin":              win,            "minWinNet":           win,            "netStakeMinWin":      win,            "maxWin":              win,            "maxWinNet":           win,            "netStakeMaxWin":      win,            "minBonus":            0,            "maxBonus":            0,            "minPercentageBonus":  0,            "maxPercentageBonus":  0,            "minOdd":              odd,            "maxOdd":              odd,            "totalOdds":           odd,            "stake":               stake,            "useGroupsStake":      False,            "stakeGross":          stake,            "stakeTaxed":          0,            "taxPercentage":       0,            "tax":                 0,            "minWithholdingTax":   0,            "maxWithholdingTax":   0,            "turnoverTax":         0,            "totalCombinations":   1,            "odds": [{                "IDSelectionType":    sel.get("typeId"),                "IDSport":            20,                "allowFixed":         True,                "compatibilityLevel": 0,                "eventCategory":      "L",                "eventDate":          event_date,                "eventId":            category_id,                "eventName":          category_name,                "fixed":              False,                "gamePlay":           1,                "incompatibleEvents": [],                "isExpired":          False,                "isLocked":           False,                "isBetBuilder":       False,                "marketId":           market["marketId"],                "marketName":         market_name,                "marketTag":          0,                "marketTypeId":       market["marketTypeId"],                "matchId":            match_id,                "matchName":          match_name,                "oddValue":           odd,                "parentEventId":      match_id,                "selectionId":        sel["id"],                "selectionName":      sel_name,                "smartCode":          0,                "specialValue":       spec_val,                "sportName":          "Table Tennis",                "tournamentId":       tournament_id,                "tournamentName":     tournament_name,                "selectionKMId":      sel["id"]          - 820_000_000,                "matchKMId":          match_id           - 30_000_000,                "marketKMId":         market["marketId"] - 240_000_000,                "isTransitioned":     False,            }],            "groupings":                [grouping],            "possibleMissingGroupings": [],            "currencyId":               -1,            "isLive":                   True,            "isVirtual":                False,            "currentEvalMotivation":    0,            "betCouponGlobalVariable": {                "currencyId":                -1,                "defaultStakeGross":         100,                "isVirtualsInstallation":    False,                "maxBetStake":               75000000,                "maxCombinationBetWin":      75000000,                "maxCombinationsByGrouping": 10000,                "maxCouponCombinations":     10000,                "maxGroupingsBetStake":      41641682,                "maxMultipleBetWin":         75000000,                "maxNoOfEvents":             40,                "maxNoOfSelections":         40,                "maxSingleBetWin":           75000000,                "minBetStake":               10,                "minBonusOdd":               1.35,                "minFlexiCutOdds":           1.05,                "minFlexiCutSelections":     5,                "minGroupingsBetStake":      5,                "stakeInnerMod0Combination": 0.01,                "stakeMod0Multiple":         0,                "stakeMod0Single":           0,                "stakeThresholdMultiple":    75000,                "stakeThresholdSingle":      7500,                "flexiCutGlobalVariable": {                    "parameters": {                        "formulaId":            1,                        "minOddThreshold":      1.05,                        "minWinningSelections": 2,                    }                },            },            "language":     "en",            "hasLive":      True,            "couponType":   1,            "allGroupings": [grouping],        },        "allowOddChanges":        True,        "allowStakeReduction":    False,        "requestTransactionId":   tx_id,        "transferStakeFromAgent": False,        "trackingData": {            "category":      "table tennis",            "product":       "sportsbook-live",            "is_quick_slip": True,            "bet_type":      "Singles",        },    }    adjust       = {"adjustId": "", "adjustIdfa": "", "gpsAdId": ""}    encoded_body = urlencode({        "data":      json.dumps(coupon, separators=(",", ":")),        "adjustIds": json.dumps(adjust, separators=(",", ":")),    }).encode()    return {        # ── identifiers for logging ───────────────────────────────────────────        "matchName":     match_name,        "specialValue":  spec_val,        "selectionSide": sel["name"],        "lineValue":     line,        # ── the only thing _place_bet() needs ─────────────────────────────────        "encoded_body":  encoded_body,        "cookie":        cookie,    }# ══════════════════════════════════════════════════════════════════════════════# Place Bet  —  single job: PUT and read response# ══════════════════════════════════════════════════════════════════════════════async def _place_bet(payload: dict, client: httpx.AsyncClient) -> bool:    """    Does exactly one thing: fires the pre-built PUT request and reads the response.    All body construction and tx_id generation happened at collection time.    """    headers = {**PLACEBET_HEADERS, "Cookie": payload["cookie"]}    t0 = time.monotonic()    try:        resp = await client.put(PLACEBET_URL, headers=headers, content=payload["encoded_body"])    except Exception as e:        print(f"[staker] req err            : {e}")        return False    elapsed_ms = int((time.monotonic() - t0) * 1000)    status     = resp.status_code    match    = payload["matchName"]    set_num  = payload["specialValue"]    line     = payload["lineValue"]    sel_side = payload["selectionSide"]    print(f"[staker] http status        : {status} [{elapsed_ms}ms]")    if status in (401, 301):        print(f"[staker] session expired    : {status} — attempting re-login")        try:            from login import login            await login()        except Exception as e:            print(f"[staker] login err          : {e}")        return False    if status != 200:        print(f"[staker] failed             : HTTP {status} — no bet placed")        return False    if not resp.text or not resp.text.strip():        print(f"[staker] empty body         : session likely expired — attempting re-login")        try:            from login import login            await login()        except Exception as e:            print(f"[staker] login err          : {e}")        return False    try:        data = resp.json()    except Exception:        print(f"[staker] parse err          : could not parse response body")        return False    coupon_code = data.get("couponCode")    resp_status = data.get("responseStatus")    errors      = data.get("errorsList", {})    messages    = data.get("messages", [])    if coupon_code:        print(f"[staker] ✓ accepted         : {match} | Set {set_num} | line={line} | side={sel_side} [{elapsed_ms}ms]")        print(f"[staker] coupon code        : {coupon_code}")        return True    if resp_status == 3:        print(f"[staker] ✗ rejected         : {match} | market closed (responseStatus=3)")        return False    print(f"[staker] ✗ rejected         : {match} | responseStatus={resp_status} | errors={errors}")    return False# ══════════════════════════════════════════════════════════════════════════════# Fetch BetKing Event# ══════════════════════════════════════════════════════════════════════════════async def _fetch_event(event_id: int, cookie: str, client: httpx.AsyncClient) -> dict | None:    url     = EVENT_URL.format(fixture_id=event_id)    headers = {        **EVENT_HEADERS,        "Referer": f"https://m.betking.com/en-ng/sports/live/{event_id}",        "Cookie":  cookie,    }    try:        resp = await client.get(url, headers=headers)        if resp.status_code == 200:            text = resp.text            if not text or not text.strip():                return None            data = resp.json()            return data if isinstance(data, dict) else None        if resp.status_code == 404:            return {"event": None, "markets": []}        print(f"[betking] HTTP {resp.status_code} for eventId={event_id}")        return None    except (httpx.TimeoutException, httpx.ConnectError, httpx.RemoteProtocolError) as e:        print(f"[betking] transient err     : {type(e).__name__} — retrying")        return None    except Exception as e:        print(f"[betking] fetch err         : {e}")        return None# ══════════════════════════════════════════════════════════════════════════════# Fetch Sportradar Delta# ══════════════════════════════════════════════════════════════════════════════async def _fetch_sr(sr_match_id: str, sr_token: str, client: httpx.AsyncClient) -> dict | None:    url = SR_URL.format(sr_match_id=sr_match_id, token=sr_token)    try:        resp = await client.get(url, headers=SR_HEADERS)        if resp.status_code == 200:            text = resp.text            if not text or not text.strip():                print(f"[sr] empty body             : sr:{sr_match_id}")                return None            try:                data = resp.json()                return data if isinstance(data, dict) else None            except Exception as e:                print(f"[sr] json parse err         : sr:{sr_match_id} — {e}")                return None        if resp.status_code == 304:            return None        print(f"[sr] HTTP {resp.status_code}             : sr:{sr_match_id}")        return None    except (httpx.TimeoutException, httpx.ConnectError, httpx.RemoteProtocolError) as e:        print(f"[sr] transient err          : {type(e).__name__} — retrying")        return None    except Exception as e:        print(f"[sr] fetch err              : sr:{sr_match_id} — {e}")        return None# ══════════════════════════════════════════════════════════════════════════════# Market Scanner# ══════════════════════════════════════════════════════════════════════════════def _scan_markets(    markets: list,    target_set: int,    event: dict,    period_scores: str,    cookie: str,) -> dict[float, dict]:    """    Scan BetKing markets for target_set and all COLLECT_LINES.    For each line found, immediately builds and encodes the FULL bet payload    including tx_id. Returns {line_value: ready_payload}.    """    found = {}    for line in COLLECT_LINES:        sel_target = "1" if line > 0 else "2"        for market in markets:            if market.get("marketTypeId") != HANDICAP_TYPE_ID:                continue            specs  = market.get("specifiers", {})            gamenr = str(specs.get("gamenr") or market.get("specialValue", ""))            if gamenr != str(target_set):                continue            if market.get("lineValue") != line:                continue            for sel in market.get("selections", []):                if sel.get("name") != sel_target:                    continue                if sel.get("status") != "VALID":                    continue                odd = sel.get("odd", {})                if odd.get("statusId") != 1:                    continue                found[line] = _build_ready_payload(                    market, sel, line, target_set, event, period_scores, cookie                )                break    return found# ══════════════════════════════════════════════════════════════════════════════# SR Trigger Check# ══════════════════════════════════════════════════════════════════════════════def _check_sr_trigger(    home: int,    away: int,    fired_triggers: set[int],    stored_payloads: dict[float, dict],    match_name: str,) -> tuple[dict | None, float | None]:    if home == away:        return None, None    loser  = min(home, away)    leader = max(home, away)    if leader <= loser:        return None, None    # Exclude set-ending scores (11:7, 7:11, 11:8, 8:11, 11:9, 9:11)    if leader >= 11:        return None, None    for loser_score, line_home_losing, line_away_losing in SR_TRIGGERS:        if loser != loser_score:            continue        if loser_score in fired_triggers:            continue        line    = line_home_losing if home < away else line_away_losing        payload = stored_payloads.get(line)        if payload is None:            print(                f"[sr] no payload stored      : {match_name} | "                f"score={home}:{away} | loser@{loser_score} | line={line} — skipping"            )            fired_triggers.add(loser_score)            return None, None        fired_triggers.add(loser_score)        return payload, line    return None, None# ══════════════════════════════════════════════════════════════════════════════# BetKing Collector Loop# ══════════════════════════════════════════════════════════════════════════════async def _run_collector(    event_id: int,    cookie: str,    client: httpx.AsyncClient,    stored_payloads: dict,    sr_id_holder: list,    stop_event: asyncio.Event,    match_name_holder: list,) -> None:    last_target_set   = None    last_boundary_set = None  # which set number we already logged boundary for    while not stop_event.is_set():        await asyncio.sleep(POLL_BETKING)        raw = await _fetch_event(event_id, cookie, client)        if raw is None:            continue        if raw.get("event") is None and raw.get("markets") == []:            print(f"[collector] match ended     : eventId={event_id}")            stop_event.set()            return        event   = raw.get("event") or {}        markets = raw.get("markets", [])        if not event:            continue        name          = event.get("name", "?")        period_scores = event.get("periodScores", "")        sets          = _parse_period_scores(period_scores)        if not sets:            continue        if match_name_holder[0] != name:            match_name_holder[0] = name        if sr_id_holder[0] is None:            sr_id = _extract_sr_id(event, markets)            if sr_id:                sr_id_holder[0] = sr_id                print(f"[collector] sr match id     : {name} | sr:{sr_id}")        cur_set  = _current_set_index(sets)        next_set = cur_set + 1        target_set = next_set if _set_has_started(sets) else cur_set        if last_target_set is not None and target_set != last_target_set:            ended_set   = cur_set - 1            started_set = cur_set            print(                f"[collector] set transition  : {name} | "                f"Set {ended_set} ended → Set {started_set} now live | "                f"now collecting for Set {target_set} | "                f"payloads kept={list(stored_payloads.keys())}"            )        last_target_set = target_set        new_finds = _scan_markets(markets, target_set, event, period_scores, cookie)        new_lines = []        for line, payload in new_finds.items():            if line not in stored_payloads:                stored_payloads[line] = payload                new_lines.append(line)            # No update needed — encoded_body is already final        if new_lines:            print(                f"[collector] stored          : {name} | "                f"Set {cur_set} live | markets for Set {target_set} | lines={new_lines}"            )        if _is_between_sets(sets) and cur_set != last_boundary_set:            last_boundary_set = cur_set            finished_set      = cur_set - 1            print(                f"[collector] set boundary    : {name} | "                f"Set {finished_set} ended | Set {cur_set} opened at 0:0 | "                f"collected for Set {cur_set}={list(stored_payloads.keys())}"            )# ══════════════════════════════════════════════════════════════════════════════# Sportradar Watcher Loop# ══════════════════════════════════════════════════════════════════════════════async def _run_sr_watcher(    match_name_holder: list,    sr_id_holder: list,    stored_payloads: dict,    fired_triggers: set,    stop_event: asyncio.Event,    bet_placed_event: asyncio.Event,    on_bet_placed,) -> None:    # SR watcher gets its own dedicated client — never shares with the collector    # This prevents ConnectTimeout from collector traffic starving SR requests    async with httpx.AsyncClient(        http2=True,        timeout=httpx.Timeout(connect=5.0, read=10.0, write=5.0, pool=5.0),        limits=httpx.Limits(max_connections=3, max_keepalive_connections=3),    ) as sr_client:        # Retry token load — don't hard-exit if not ready at startup        sr_token = ""        while not stop_event.is_set() and not sr_token:            sr_token = _load_sr_token()            if not sr_token:                print(f"[sr watcher] no token       : retrying in 5s")                await asyncio.sleep(5.0)        if not sr_token:            return  # stop_event fired while waiting        print(f"[sr watcher] token loaded   : ready")        watching_set:       int | None = None        last_score:         tuple | None = None        first_fetch_logged              = False        while not stop_event.is_set():            await asyncio.sleep(POLL_SR)            if bet_placed_event.is_set():                continue            sr_match_id = sr_id_holder[0]            if sr_match_id is None:                continue            sr_data = await _fetch_sr(sr_match_id, sr_token, sr_client)            if sr_data is None:                continue            if not first_fetch_logged:                first_fetch_logged = True                print(f"[sr watcher] first fetch    : sr:{sr_match_id} | keys={list(sr_data.keys())}")            period_num = _sr_current_period(sr_data)            score      = _sr_last_period_score(sr_data, period_num) if period_num else None            if score is None or period_num is None:                continue            home, away = score            match_name = match_name_holder[0]            if watching_set is None:                watching_set = period_num                print(f"[sr watcher] watching set   : {match_name} | set={watching_set}")            elif period_num != watching_set:                print(                    f"[sr watcher] set changed    : {match_name} | "                    f"{watching_set} → {period_num} | resetting triggers"                )                fired_triggers.clear()                watching_set = period_num                last_score   = None            if (home + away) == 0:                continue            if score != last_score:                last_score     = score                loser_score    = min(home, away)                leader         = max(home, away)                trigger_losers = {t[0] for t in SR_TRIGGERS}                # ── Trigger check runs FIRST — bet fires before any logging ──                payload, line = _check_sr_trigger(                    home, away, fired_triggers, stored_payloads, match_name                )                if payload is not None:                    # Fire immediately — zero prints before this call                    success = await _place_bet(payload, sr_client)                    # Retrospective logging — after bet is already in flight                    losing_side = "home" if home < away else "away"                    print(                        f"[sr watcher] score          : {match_name} | "                        f"set={watching_set} | {home}:{away}"                    )                    print(                        f"[sr watcher] trigger        : {match_name} | "                        f"score={home}:{away} | loser@{loser_score} | "                        f"losing={losing_side} | line={line}"                    )                    if success:                        bet_placed_event.set()                        if on_bet_placed:                            await on_bet_placed()                elif loser_score in trigger_losers and leader < 11:                    # Interesting score but no trigger yet — log score only                    print(                        f"[sr watcher] score          : {match_name} | "                        f"set={watching_set} | {home}:{away}"                    )# ══════════════════════════════════════════════════════════════════════════════# Main Analyze Entry Point# ══════════════════════════════════════════════════════════════════════════════async def analyze(event_id: int, on_bet_placed=None) -> None:    print(f"[analyzer] worker started   : eventId={event_id}")    cookie = _load_cookie()    # ── Per-worker local state — fully isolated per match ─────────────────────    stored_payloads:   dict[float, dict] = {}    fired_triggers:    set[int]          = set()    sr_id_holder:      list              = [None]    match_name_holder: list              = ["?"]    stop_event         = asyncio.Event()    bet_placed_event   = asyncio.Event()    async with httpx.AsyncClient(        http2=True,        timeout=httpx.Timeout(connect=5.0, read=10.0, write=5.0, pool=5.0),        limits=httpx.Limits(max_connections=5, max_keepalive_connections=5),    ) as client:        collector_task = asyncio.create_task(            _run_collector(                event_id, cookie, client,                stored_payloads, sr_id_holder,                stop_event, match_name_holder,            )        )        watcher_task = asyncio.create_task(            _run_sr_watcher(                match_name_holder, sr_id_holder,                stored_payloads, fired_triggers,                stop_event, bet_placed_event,                on_bet_placed,            )        )        await stop_event.wait()        collector_task.cancel()        watcher_task.cancel()        try:            await asyncio.gather(collector_task, watcher_task, return_exceptions=True)        except Exception:            pass    print(f"[analyzer] worker released  : eventId={event_id}")